  @Input() isSubmitDisabled = false;
  @Input() isCancelDisabled = true;
  @Input() canEdit = true;
  @Input() formRequestState: RequestState | RequestState[] = RequestState.IDLE;

  @Output() submitted = new EventEmitter<void>();
  @Output() cancelled = new EventEmitter<void>();

  onSubmit(): void {
    this.submitted.emit();
  }

  onCancel(): void {
    this.cancelled.emit();
  }
}

